SELECT result_tags AS tags, any(timestamp) AS timestamp, any(value) AS value FROM (SELECT if((lhs_is_info_metric) OR length(rhs_groups) = 0, lhs_original_group, arraySort(tag -> tag.1, arrayConcat(lhs_original_group, arrayDistinct(arrayFlatten(arrayMap(tags -> arrayFilter(tag -> NOT has(['__name__', 'instance', 'job'], tag.1) AND NOT has(arrayMap(tag -> tag.1, lhs_original_group), tag.1), tags), rhs_groups)))))) AS result_tags, timestamp AS timestamp, value AS value FROM (SELECT lhs.original_group AS lhs_original_group, lhs.timestamp AS timestamp, lhs.value AS value, (arrayElement(arrayMap(tag -> tag.2, arrayFilter(tag -> tag.1 = '__name__', lhs.original_group)), 1) = {info_lhs_name_matcher_0_value:String}) AS lhs_is_info_metric, groupArrayIf(rhs.original_group, length(rhs.original_group) > 0) AS rhs_groups FROM (SELECT tags AS original_group, arraySort(tag -> tag.1, arrayFilter(tag -> has(['instance', 'job'], tag.1), tags)) AS join_group, timestamp AS timestamp, value AS value FROM (
    SELECT series.tags AS tags, fromUnixTimestamp64Milli(1700000000000) AS timestamp, argMax(d.value, d.timestamp) AS value FROM timeSeriesData(`observability`.`prometheus`) AS d INNER JOIN (
        SELECT DISTINCT src.id, arrayConcat([tuple('__name__', src.metric_name)], arrayMap((k, v) -> tuple(k, v), mapKeys(src.tags), mapValues(src.tags))) AS tags FROM timeSeriesTags(`observability`.`prometheus`) AS src WHERE src.metric_name = {info_lhs_instant_matcher_0_value:String} AND src.tags[concat('', {info_lhs_instant_matcher_1_key:String})] = {info_lhs_instant_matcher_1_value:String} AND src.max_time >= fromUnixTimestamp64Milli({info_lhs_required_start_ms:Int64}) AND src.min_time <= fromUnixTimestamp64Milli({info_lhs_required_end_ms:Int64})
    ) AS series ON d.id = series.id WHERE d.timestamp >= fromUnixTimestamp64Milli({info_lhs_required_start_ms:Int64}) AND d.timestamp <= fromUnixTimestamp64Milli({info_lhs_required_end_ms:Int64}) GROUP BY d.id, series.tags HAVING NOT isNaN(value) ORDER BY tags
)) AS lhs LEFT JOIN (SELECT any(original_group) AS original_group, join_group AS join_group, any(timestamp) AS timestamp, any(value) AS value, metric_name FROM (SELECT original_group, join_group, timestamp, value, arrayElement(arrayMap(tag -> tag.2, arrayFilter(tag -> tag.1 = '__name__', original_group)), 1) AS metric_name FROM (SELECT tags AS original_group, arraySort(tag -> tag.1, arrayFilter(tag -> has(['instance', 'job'], tag.1), tags)) AS join_group, timestamp AS timestamp, value AS value FROM (
    SELECT series.tags AS tags, fromUnixTimestamp64Milli(1700000000000) AS timestamp, argMax(d.value, d.timestamp) AS value FROM timeSeriesData(`observability`.`prometheus`) AS d INNER JOIN (
        SELECT DISTINCT src.id, arrayConcat([tuple('__name__', src.metric_name)], arrayMap((k, v) -> tuple(k, v), mapKeys(src.tags), mapValues(src.tags))) AS tags FROM timeSeriesTags(`observability`.`prometheus`) AS src WHERE src.metric_name = {instant_matcher_0_value:String} AND src.max_time >= fromUnixTimestamp64Milli({required_start_ms:Int64}) AND src.min_time <= fromUnixTimestamp64Milli({required_end_ms:Int64})
    ) AS series ON d.id = series.id WHERE d.timestamp >= fromUnixTimestamp64Milli({required_start_ms:Int64}) AND d.timestamp <= fromUnixTimestamp64Milli({required_end_ms:Int64}) GROUP BY d.id, series.tags HAVING NOT isNaN(value) ORDER BY tags
)) AS rhs_input) AS rhs_checked GROUP BY join_group, metric_name HAVING throwIf(count() > 1, 'found duplicate series for info metric on identifying labels') = 0) AS rhs ON lhs.join_group = rhs.join_group GROUP BY lhs.original_group, lhs.join_group, lhs.timestamp, lhs.value, (arrayElement(arrayMap(tag -> tag.2, arrayFilter(tag -> tag.1 = '__name__', lhs.original_group)), 1) = {info_lhs_name_matcher_0_value:String})) AS joined_rows) AS joined_result_rows GROUP BY result_tags ORDER BY result_tags
SETTINGS allow_experimental_time_series_table = 1
FORMAT JSONEachRow
